# Deepwick colorscheme for ranger (https://github.com/deepwick/ranger).
# ranger draws through curses, so colors are the nearest xterm-256 matches;
# backgrounds are left to the terminal except for the selection.

from __future__ import (absolute_import, division, print_function)

from ranger.gui.color import bold, default_colors, normal
from ranger.gui.colorscheme import ColorScheme

# BEGIN generated by generate.py
C = {
    "background": 233,
    "foreground": 188,
    "selection": 24,
    "overlay": 237,
    "muted": 66,
    "comment": 103,
    "blue": 75,
    "lightBlue": 117,
    "cyan": 39,
    "teal": 43,
    "yellow": 187,
    "gold": 179,
    "rose": 167,
    "magenta": 176,
    "green": 71,
    "red": 203,
}
# END generated by generate.py


class Deepwick(ColorScheme):
    progress_bar_color = C["blue"]

    def use(self, context):  # pylint: disable=too-many-branches,too-many-statements
        fg, bg, attr = default_colors

        if context.reset:
            return default_colors

        elif context.in_browser:
            attr = normal
            if context.selected:
                bg = C["selection"]
            if context.empty or context.error:
                fg = C["red"]
            if context.border:
                fg = C["overlay"]
            if context.media:
                fg = C["magenta"]
            if context.container:
                fg = C["rose"]
            if context.directory:
                attr |= bold
                fg = C["blue"]
            elif context.executable and not \
                    any((context.media, context.container,
                         context.fifo, context.socket)):
                attr |= bold
                fg = C["green"]
            if context.socket or context.fifo or context.device:
                fg = C["gold"]
                if context.device:
                    attr |= bold
            if context.link:
                attr &= ~bold
                fg = C["cyan"] if context.good else C["red"]
            if context.tag_marker and not context.selected:
                attr |= bold
                fg = C["gold"]
            if not context.selected and (context.cut or context.copied):
                fg = C["muted"]
            if context.main_column:
                if context.selected:
                    attr |= bold
                if context.marked:
                    attr |= bold
                    fg = C["yellow"]
            if context.badinfo:
                fg = C["red"]
            if context.inactive_pane:
                fg = C["comment"]

        elif context.in_titlebar:
            if context.hostname:
                fg = C["red"] if context.bad else C["green"]
            elif context.directory:
                fg = C["blue"]
            elif context.tab:
                if context.good:
                    fg = C["foreground"]
                    bg = C["selection"]
            elif context.link:
                fg = C["cyan"]
            attr |= bold

        elif context.in_statusbar:
            if context.permissions:
                if context.good:
                    fg = C["green"]
                elif context.bad:
                    fg = C["red"]
            if context.owner:
                fg = C["lightBlue"]
            if context.group or context.mtime:
                fg = C["comment"]
            if context.nlink:
                fg = C["muted"]
            if context.link:
                fg = C["red"] if context.bad else C["cyan"]
            if context.marked:
                attr |= bold
                fg = C["background"]
                bg = C["gold"]
            if context.frozen:
                attr |= bold
                fg = C["background"]
                bg = C["cyan"]
            if context.message:
                if context.bad:
                    attr |= bold
                    fg = C["red"]
            if context.vcsinfo:
                fg = C["blue"]
                attr &= ~bold
            if context.vcscommit:
                fg = C["yellow"]
                attr &= ~bold
            if context.vcsdate:
                fg = C["comment"]
                attr &= ~bold

        if context.text:
            if context.highlight:
                bg = C["selection"]

        if context.in_taskview:
            if context.title:
                fg = C["blue"]

            if context.selected:
                bg = C["selection"]

            if context.loaded:
                if context.selected:
                    fg = self.progress_bar_color
                else:
                    bg = self.progress_bar_color

        if context.vcsfile and not context.selected:
            attr &= ~bold
            if context.vcsconflict:
                fg = C["red"]
            elif context.vcsuntracked:
                fg = C["teal"]
            elif context.vcschanged:
                fg = C["blue"]
            elif context.vcsunknown:
                fg = C["red"]
            elif context.vcsstaged:
                fg = C["green"]
            elif context.vcssync:
                fg = C["green"]
            elif context.vcsignored:
                fg = C["muted"]

        elif context.vcsremote and not context.selected:
            attr &= ~bold
            if context.vcssync or context.vcsnone:
                fg = C["green"]
            elif context.vcsbehind:
                fg = C["red"]
            elif context.vcsahead:
                fg = C["blue"]
            elif context.vcsdiverged:
                fg = C["magenta"]
            elif context.vcsunknown:
                fg = C["red"]

        return fg, bg, attr
